/// Skill tree names per class (player txt row), pages 1, 2, 3.
pub const TREES: [[&str; 3]; 8] = [
    ["Bow and Crossbow", "Passive and Magic", "Javelin and Spear"],
    ["Fire", "Lightning", "Cold"],
    ["Curses", "Poison and Bone", "Summoning"],
    ["Combat", "Offensive Auras", "Defensive Auras"],
    ["Combat", "Masteries", "Warcries"],
    ["Summoning", "Shape Shifting", "Elemental"],
    ["Traps", "Shadow Disciplines", "Martial Arts"],
    ["Demon", "Eldritch", "Chaos"],
];

/// Classless skills a player can put on a mouse button: (id, displayed name).
pub const BASIC: &[(u16, &str)] = &[
    (0, "Attack"),
    (1, "Kick"),
    (2, "Throw"),
    (3, "Unsummon"),
    (4, "Left Hand Throw"),
    (5, "Left Hand Swing"),
    (217, "Scroll of Identify"),
    (218, "Tome of Identify"),
    (219, "Scroll of Town Portal"),
    (220, "Tome of Town Portal"),
];

/// The class skill with skills.txt id `id`.
pub fn skill(id: u16) -> Option<&'static SkillInfo> {
    SKILLS
        .binary_search_by_key(&id, |s| s.id)
        .ok()
        .and_then(|i| SKILLS.get(i))
}

/// The displayed name of skill `id`: a class skill or a [`BASIC`] one.
pub fn name(id: u16) -> Option<&'static str> {
    skill(id)
        .map(|s| s.name)
        .or_else(|| BASIC.iter().find(|(i, _)| *i == id).map(|(_, n)| *n))
}
